function getExplorerDragAutoScrollVelocity(args: {
  viewport: HTMLDivElement;
  pointer: { x: number; y: number };
}): number {
  const rect = args.viewport.getBoundingClientRect();
  const withinHorizontalBounds =
    args.pointer.x >= rect.left - EXPLORER_DRAG_AUTOSCROLL_OUTSET_PX &&
    args.pointer.x <= rect.right + EXPLORER_DRAG_AUTOSCROLL_OUTSET_PX;
  const withinVerticalBounds =
    args.pointer.y >= rect.top - EXPLORER_DRAG_AUTOSCROLL_OUTSET_PX &&
    args.pointer.y <= rect.bottom + EXPLORER_DRAG_AUTOSCROLL_OUTSET_PX;
  if (!withinHorizontalBounds || !withinVerticalBounds) {
    return 0;
  }

  const maxScrollTop = args.viewport.scrollHeight - args.viewport.clientHeight;
  if (maxScrollTop <= 0) {
    return 0;
  }

  const topDistance = args.pointer.y - rect.top;
  const bottomDistance = rect.bottom - args.pointer.y;
  const edgeSize = EXPLORER_DRAG_AUTOSCROLL_EDGE_PX;

  const resolveVelocity = (distance: number, direction: 1 | -1): number => {
    const clampedDistance = Math.max(0, Math.min(edgeSize, distance));
    const intensity = 1 - clampedDistance / edgeSize;
    if (intensity <= 0) {
      return 0;
    }
    const speed =
      EXPLORER_DRAG_AUTOSCROLL_MIN_SPEED_PX_PER_SECOND +
      (EXPLORER_DRAG_AUTOSCROLL_MAX_SPEED_PX_PER_SECOND -
        EXPLORER_DRAG_AUTOSCROLL_MIN_SPEED_PX_PER_SECOND) *
        intensity *
        intensity;
    return speed * direction;
  };

  if (topDistance <= edgeSize && args.viewport.scrollTop > 0) {
    return resolveVelocity(topDistance, -1);
  }
  if (bottomDistance <= edgeSize && args.viewport.scrollTop < maxScrollTop) {
    return resolveVelocity(bottomDistance, 1);
  }
  return 0;
}

function applyEditorSearchFocus(
  editor: any,
  monaco: any,
  focusTarget: EditorSearchFocusTarget | null,
) {
  editor.layout?.();

  if (!focusTarget) {
    return;
  }

  const model = editor.getModel?.();
  if (!model) {
    return;
  }

  const lineNumber = clampSearchFocusLine(
    focusTarget.lineNumber,
    model.getLineCount(),
  );
  const lineContent = model.getLineContent(lineNumber);
  const { startColumn, endColumn } = findSearchFocusColumns(
    lineContent,
    focusTarget.searchString,
  );

  if (focusTarget.searchString) {
    const range = new monaco.Range(
      lineNumber,
      startColumn,
      lineNumber,
      endColumn,
    );
    editor.setSelection?.(range);
    editor.revealRangeInCenter?.(range);
    editor.focus?.();
    void editor.getAction?.(MONACO_FIND_WITH_ARGS_ACTION)?.run({
      searchString: focusTarget.searchString,
      isRegex: false,
      matchWholeWord: false,
      isCaseSensitive: false,
      findInSelection: false,
    });
    return;
  }

  editor.setPosition?.({ lineNumber, column: 1 });
  editor.revealLineInCenter?.(lineNumber);
  editor.focus?.();
}

function SearchAwareCodeView({
  appearance,
  path,
  value,
  language,
  focusTarget,
  onChange,
  onCursorPositionChange,
  options,
}: {
  appearance?: ResolvedOverlayAppearance;
  path: string;
  value: string;
  language: string;
  focusTarget: EditorSearchFocusTarget | null;
  onChange?: (value: string) => void;
  onCursorPositionChange?: (position: EditorCursorPosition) => void;
  options: MonacoEditorOptions;
}) {
  const editorRef = useRef<any>(null);
  const monacoRef = useRef<any>(null);
  const cursorListenerRef = useRef<{ dispose(): void } | null>(null);
  const monacoThemeId = resolveExplorerMonacoThemeId(appearance);

  const publishCursorPosition = useCallback(
    (editor: any) => {
      const position = editor.getPosition?.();
      if (!position) {
        return;
      }
      onCursorPositionChange?.({
        lineNumber: position.lineNumber,
        column: position.column,
      });
    },
    [onCursorPositionChange],
  );

  const handleMount = useCallback(
    (editor: any, monaco: any) => {
      editorRef.current = editor;
      monacoRef.current = monaco;
      applyExplorerMonacoTheme(monaco, appearance);
      cursorListenerRef.current?.dispose?.();
      cursorListenerRef.current =
        editor.onDidChangeCursorPosition?.(
          (event: { position: EditorCursorPosition }) => {
            onCursorPositionChange?.({
              lineNumber: event.position.lineNumber,
              column: event.position.column,
            });
          },
        ) ?? null;
      publishCursorPosition(editor);
      window.requestAnimationFrame(() => {
        window.requestAnimationFrame(() => {
          editor.layout?.();
          applyEditorSearchFocus(editor, monaco, focusTarget);
          publishCursorPosition(editor);
        });
      });
    },
    [appearance, focusTarget, onCursorPositionChange, publishCursorPosition],
  );

  const handleBeforeMount = useCallback(
    (monaco: any) => {
      applyExplorerMonacoTheme(monaco, appearance);
    },
    [appearance],
  );

  useEffect(() => {
    if (!editorRef.current || !monacoRef.current) {
      return;
    }

    applyExplorerMonacoTheme(monacoRef.current, appearance);
    const frame = window.requestAnimationFrame(() => {
      applyEditorSearchFocus(editorRef.current, monacoRef.current, focusTarget);
      publishCursorPosition(editorRef.current);
    });

    return () => {
      window.cancelAnimationFrame(frame);
    };
  }, [appearance, focusTarget?.requestId, path, publishCursorPosition, value]);

  useEffect(() => {
    if (!editorRef.current) {
      return;
    }
    publishCursorPosition(editorRef.current);
  }, [path, publishCursorPosition, value]);

  useEffect(
    () => () => {
      cursorListenerRef.current?.dispose?.();
      cursorListenerRef.current = null;
    },
    [],
  );

  return (
    <Suspense fallback={<EditorFallback label="Loading editor…" />}>
      <LazyMonacoEditor
        path={path}
        height="100%"
        language={language || "plaintext"}
        value={value}
        theme={monacoThemeId}
        beforeMount={handleBeforeMount}
        onMount={handleMount}
        saveViewState
        onChange={
          onChange ? (nextValue) => onChange(nextValue ?? "") : undefined
        }
        options={options}
      />
    </Suspense>
  );
}

function EditorFallback({ label }: { label: string }) {
  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        display: "grid",
        placeItems: "center",
        background: "var(--overlay-explorer-code-bg)",
        color: EXP.muted,
        fontSize: 11,
      }}
    >
      {label}
    </div>
  );
}

const PREVIEW_PLUGIN_HOST_COMPACT_WIDTH = 1040;
const PREVIEW_PLUGIN_HOST_DENSE_WIDTH = 820;

function getPreviewPluginAppearance(appearance?: ResolvedOverlayAppearance) {
  return {
    theme:
      appearance?.theme ??
      ({
        id: "operator",
        name: "Operator",
        palette: {} as never,
        effects: {} as never,
        xterm: {} as never,
      } satisfies ResolvedOverlayAppearance["theme"]),
    fonts: appearance?.fonts ?? {
      ui: "var(--overlay-font-ui)",
      mono: "var(--overlay-font-mono)",
    },
    cssVars: appearance?.cssVars ?? {},
  };
}

function buildPreviewPluginHostContext(
  width: number,
  height: number,
  zoom: number,
): OverlayPluginPreviewHostContext {
  const compact = width > 0 && width <= PREVIEW_PLUGIN_HOST_COMPACT_WIDTH;
  return {
    mode: "preview-pane",
    width,
    height,
    zoom,
    compact,
    density:
      width > 0 && width <= PREVIEW_PLUGIN_HOST_DENSE_WIDTH
        ? "compact"
        : "regular",
  };
}

class PreviewPluginErrorBoundary extends React.Component<
  { children: React.ReactNode; laneTitle: string },
  { error: string | null }
> {
  constructor(props: { children: React.ReactNode; laneTitle: string }) {
    super(props);
    this.state = { error: null };
  }

  static getDerivedStateFromError(error: unknown) {
    return { error: String(error) };
  }

  override componentDidUpdate(prevProps: { laneTitle: string }) {
    if (prevProps.laneTitle !== this.props.laneTitle && this.state.error) {
      this.setState({ error: null });
    }
  }

  override render() {
    if (!this.state.error) {
      return this.props.children;
    }

    return (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "grid",
          placeItems: "center",
          padding: 24,
          background: "var(--overlay-explorer-preview-bg)",
        }}
      >
        <div
          style={{
            maxWidth: 520,
            borderRadius: 18,
            border:
              "1px solid color-mix(in srgb, var(--overlay-danger) 38%, transparent)",
            background:
              "color-mix(in srgb, var(--overlay-danger) 16%, transparent)",
            padding: 18,
            color: "var(--overlay-text-primary)",
          }}
        >
          <div style={{ fontSize: 15, fontWeight: 700 }}>
            {this.props.laneTitle} threw while rendering
          </div>
          <pre
            style={{
              marginTop: 12,
              padding: 12,
              borderRadius: 12,
              background: "var(--overlay-bg-card-hover)",
              color: "var(--overlay-danger)",
              whiteSpace: "pre-wrap",
              fontSize: 12,
              lineHeight: 1.5,
            }}
          >
            {this.state.error}
          </pre>
        </div>
      </div>
    );
  }
}

